   }

   seen := -1
   for time := range this.keyStore[key] {
       if time <= timestamp {
           seen = max(seen, time)
       }
   }

   if seen == -1 {
       return ""
   }
   values := this.keyStore[key][seen]
   return values[len(values)-1]
}

