        guard let values = keyStore[key] else {
            return ""
        }

        var res = ""
        var l = 0, r = values.count - 1

        while l <= r {
            let m = (l + r) / 2
            if values[m].1 <= timestamp {
                res = values[m].0
                l = m + 1
            } else {
                r = m - 1
            }
        }

        return res
    }
}
